<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { supabase } from '@/lib/supabase'
type Capsule={id:string;title:string;unlock_date:string;can_open:boolean}
const capsules=ref<Capsule[]>([]), title=ref(''), message=ref(''), date=ref(''), error=ref(''), saving=ref(false), opened=ref('')
async function load(){const result=await supabase.rpc('list_capsules');if(result.error)throw result.error;capsules.value=result.data as unknown as Capsule[]}
onMounted(()=>{void load().catch(e=>error.value=e.message)})
async function create(){error.value='';saving.value=true;try{const result=await supabase.rpc('create_capsule',{capsule_title:title.value,capsule_message:message.value,opens_on:date.value});if(result.error)throw result.error;title.value='';message.value='';date.value='';await load()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
async function open(id:string){error.value='';try{const result=await supabase.rpc('open_capsule',{capsule_id:id});if(result.error)throw result.error;opened.value=(result.data as {message:string}).message;await load()}catch(e){error.value=(e as Error).message}}
</script>
<template><main class="capsule-page"><header class="capsule-hero"><p class="eyebrow">A SMALL GIFT TO YOUR FUTURE SELF</p><h1>Time capsules</h1><p>Gather a thought from today and leave it somewhere in tomorrow.</p><div class="capsule-seal" aria-hidden="true">✳</div></header>
<div v-if="error" role="alert" class="capsule-alert">{{error}}</div><div class="capsule-layout"><form @submit.prevent="create" class="capsule-paper"><div class="paper-heading"><span class="paper-icon">⌁</span><div><h2>Seal a little memory</h2><p>Only you can read it, once its day arrives.</p></div></div><label class="capsule-field">Give it a title<input v-model="title" required maxlength="255" placeholder="A note for later…" /></label><label class="capsule-field">What would you like to remember?<textarea v-model="message" required rows="7" placeholder="Write to the you who will open this…" /></label><label class="capsule-field">Let it open on<input v-model="date" required type="date" :min="new Date().toISOString().slice(0,10)" /><small>The date is shown in UTC.</small></label><button :disabled="saving" class="seal-button">{{saving?'Sealing your words…':'Seal this capsule'}} <span>✳</span></button></form>
<section class="capsule-shelf"><div class="shelf-heading"><div><p class="eyebrow">YOUR LITTLE TIMEKEEPERS</p><h2>On the shelf</h2></div><span>{{capsules.length.toString().padStart(2,'0')}}</span></div><article v-if="opened" class="opened-note"><p>OPENED, JUST FOR YOU</p><div>{{opened}}</div><button aria-label="Dismiss opened note" @click="opened=''">Close note ×</button></article><div v-if="!capsules.length" class="capsule-empty"><span>◷</span><h3>Nothing waiting just yet.</h3><p>When you seal a capsule, it will find a home here until its opening day.</p></div><article v-for="(capsule,index) in capsules" :key="capsule.id" class="capsule-item" :class="{'is-ready':capsule.can_open}"><div class="capsule-item-top"><span class="capsule-index">{{String(index+1).padStart(2,'0')}}</span><span class="capsule-status">{{capsule.can_open?'READY TO OPEN':'SEALED'}}</span></div><h3>{{capsule.title}}</h3><p class="opens-on">{{capsule.can_open?'Its day has arrived':'Opens'}} · {{new Date(`${capsule.unlock_date}T12:00:00`).toLocaleDateString('en-PH',{month:'long',day:'numeric',year:'numeric'})}}</p><button :disabled="!capsule.can_open" @click="open(capsule.id)" class="open-button">{{capsule.can_open?'Open your capsule':'Still waiting'}} <span>{{capsule.can_open?'↗':'◷'}}</span></button></article></section></div></main></template>
<style scoped>
.capsule-page{--wine:#74283c;--ink:#392d28;--muted:#827568;--line:#e6dccd;max-width:1050px;margin:auto;padding:32px 20px 75px;color:var(--ink)}.capsule-hero{position:relative;padding:28px 32px 31px;border:1px solid #e4d6c1;background:linear-gradient(112deg,#f2e8d8,#fbf8f0 72%);overflow:hidden}.eyebrow{font-size:9px;letter-spacing:.18em;color:#947852}.capsule-hero h1{margin:10px 0;color:var(--wine);font:clamp(36px,5vw,49px) Georgia,serif}.capsule-hero>p:last-of-type{max-width:540px;color:var(--muted);line-height:1.65}.capsule-seal{position:absolute;right:8%;top:50%;transform:translateY(-50%);display:grid;place-items:center;width:82px;height:82px;border:1px solid #c8b595;border-radius:50%;color:var(--wine);font:32px Georgia,serif;box-shadow:inset 0 0 0 5px #f2e8d8,inset 0 0 0 6px #c8b595}.capsule-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(260px,.85fr);gap:23px;margin-top:23px}.capsule-paper,.capsule-shelf{padding:24px;background:#fcfaf5;border:1px solid var(--line);box-shadow:0 12px 35px #45321c08}.paper-heading,.shelf-heading{display:flex;align-items:center;gap:13px;padding-bottom:17px;border-bottom:1px solid var(--line);margin-bottom:18px}.paper-icon{display:grid;place-items:center;width:38px;height:38px;border:1px solid #d4c4a9;border-radius:50%;color:var(--wine);font-size:22px}.paper-heading h2,.shelf-heading h2{margin:0;color:var(--wine);font:22px Georgia,serif}.paper-heading p{margin:4px 0 0;color:var(--muted);font-size:12px}.capsule-field{display:grid;gap:7px;margin:15px 0;color:#5c4d41;font-size:12px;font-weight:600}.capsule-field input,.capsule-field textarea{width:100%;padding:12px;border:1px solid #ddd1c0;border-radius:3px;background:#fffefa;color:var(--ink);font:14px Georgia,serif}.capsule-field textarea{resize:vertical;line-height:1.7}.capsule-field small{color:var(--muted);font-weight:400}.seal-button,.open-button{display:flex;justify-content:space-between;align-items:center;gap:20px;min-height:45px;padding:0 15px;border:0;border-radius:3px;background:var(--wine);color:#fffaf2;cursor:pointer;font-size:12px}.seal-button{width:100%;margin-top:8px}.seal-button:disabled{opacity:.6}.shelf-heading{justify-content:space-between}.shelf-heading .eyebrow{margin:0 0 6px}.shelf-heading>span{color:#ae9c7d;font:24px Georgia,serif}.capsule-item{padding:16px 2px;border-bottom:1px solid var(--line)}.capsule-item-top{display:flex;justify-content:space-between;align-items:center}.capsule-index{color:#a18e70;font:14px Georgia,serif}.capsule-status{font-size:8px;letter-spacing:.15em;color:#9a8b74}.is-ready .capsule-status{color:#667455}.capsule-item h3{margin:11px 0 5px;color:var(--wine);font:20px Georgia,serif}.opens-on{color:var(--muted);font-size:11px}.open-button{width:100%;margin-top:13px;background:#f1ebdf;color:var(--wine);border:1px solid #ddd0bc}.open-button:disabled{color:#8f877c;cursor:not-allowed}.capsule-empty{padding:30px 8px;text-align:center;color:var(--muted)}.capsule-empty>span{color:#a58f6d;font:34px Georgia,serif}.capsule-empty h3{color:var(--wine);font:19px Georgia,serif}.capsule-empty p{font-size:12px;line-height:1.6}.opened-note{padding:17px;margin-bottom:16px;border:1px solid #c5cfb9;background:#eff1e9}.opened-note>p{margin:0 0 9px;color:#6d775e;font-size:9px;letter-spacing:.14em}.opened-note>div{white-space:pre-wrap;line-height:1.7;font:15px Georgia,serif}.opened-note button{margin-top:12px;padding:0;border:0;background:none;color:var(--wine);font-size:11px;cursor:pointer}.capsule-alert{margin-top:15px;padding:12px;background:#f9e7e3;color:#842e25;font-size:13px}@media(max-width:700px){.capsule-page{padding:18px 14px 50px}.capsule-layout{grid-template-columns:1fr}.capsule-paper,.capsule-shelf{padding:19px}.capsule-seal{right:7%;width:57px;height:57px;font-size:22px;opacity:.65}.capsule-hero{padding:23px 20px}.capsule-hero>p:last-of-type{max-width:75%}}
</style>
